package com.primehr.learningdevelopment.delivery.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.*;import java.time.*;
@Entity@Table(name="ld_offering_session",uniqueConstraints=@UniqueConstraint(name="uk_ld_offering_session_order",columnNames={"agency_id","offering_id","display_order"}))
public class LdOfferingSession extends RspAuditedEntity{@Column(name="offering_id",nullable=false,length=36)private String offeringId;@Column(nullable=false,length=200)private String title;@Column(name="starts_at",nullable=false)private OffsetDateTime startsAt;@Column(name="ends_at",nullable=false)private OffsetDateTime endsAt;@Column(name="venue_or_platform",nullable=false,length=1000)private String venueOrPlatform;@Column(name="credited_hours",nullable=false,precision=9,scale=2)private BigDecimal creditedHours;@Column(name="display_order",nullable=false)private int displayOrder;protected LdOfferingSession(){}public LdOfferingSession(String agency,String offering,String title,OffsetDateTime starts,OffsetDateTime ends,String venue,BigDecimal hours,int order){super(agency);offeringId=requiredText(offering,"offeringId");this.title=requiredText(title,"title");if(starts==null||ends==null||!ends.isAfter(starts))throw new IllegalArgumentException("Session end must be after its start");startsAt=starts;endsAt=ends;venueOrPlatform=requiredText(venue,"venueOrPlatform");if(hours==null||hours.signum()<=0)throw new IllegalArgumentException("creditedHours must be positive");creditedHours=hours.setScale(2,RoundingMode.HALF_UP);if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;}public String getOfferingId(){return offeringId;}public String getTitle(){return title;}public OffsetDateTime getStartsAt(){return startsAt;}public OffsetDateTime getEndsAt(){return endsAt;}public String getVenueOrPlatform(){return venueOrPlatform;}public BigDecimal getCreditedHours(){return creditedHours;}public int getDisplayOrder(){return displayOrder;}}
